-- ------------------------- info -------------------------
-- @@ver: 1_000_054
-- @@info: 已执行旧版1.0.54数据库的流程定义历史版本手动补丁
-- ------------------------- info -------------------------

-- 仅在已执行旧版完整1.0.54的目标数据库手动运行；新库使用resources下完整脚本。
-- 此文件位于docs/sql，不参与框架自动升级，不新增升级版本，不修改升级记录。
-- 执行前停止应用，确认没有运行中的任务；执行后只启动已接入版本表的新代码。
-- 测试库专用：清理未关联版本的旧流程运行及其节点/业务日志，然后删除flow_snapshot。
-- 保留任务配置、已关联版本的运行、普通独立任务日志；不执行任务、不回填旧快照。

BEGIN;

CREATE TABLE IF NOT EXISTS "base_job_definition_version" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "job_id" integer NOT NULL,
    "version_no" integer NOT NULL,
    "job_name" varchar(255) NOT NULL,
    "detail_log_enabled" boolean NOT NULL DEFAULT false,
    "flow_definition" text NOT NULL,
    "content_hash" char(64) NOT NULL,
    "crt_time" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "crt_user" varchar(32) DEFAULT NULL,
    "crt_name" varchar(255) DEFAULT NULL,
    "crt_host" varchar(255) DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_job_definition_version" UNIQUE ("job_id", "version_no")
);
COMMENT ON TABLE "base_job_definition_version" IS 'BASE-不可变流程定义历史版本';
COMMENT ON COLUMN "base_job_definition_version"."id" IS '流程定义版本ID';
COMMENT ON COLUMN "base_job_definition_version"."job_id" IS '所属流程任务配置ID';
COMMENT ON COLUMN "base_job_definition_version"."version_no" IS '任务内递增版本号，从1开始';
COMMENT ON COLUMN "base_job_definition_version"."job_name" IS '任务名称快照';
COMMENT ON COLUMN "base_job_definition_version"."detail_log_enabled" IS '详细日志开关快照:false关闭/true开启';
COMMENT ON COLUMN "base_job_definition_version"."flow_definition" IS '不可变流程定义JSON，包含节点位置';
COMMENT ON COLUMN "base_job_definition_version"."content_hash" IS '名称、日志开关及规范化定义的SHA-256，应用计算';
COMMENT ON COLUMN "base_job_definition_version"."crt_time" IS '版本创建时间';
COMMENT ON COLUMN "base_job_definition_version"."crt_user" IS '版本创建用户ID';
COMMENT ON COLUMN "base_job_definition_version"."crt_name" IS '版本创建用户名';
COMMENT ON COLUMN "base_job_definition_version"."crt_host" IS '版本创建来源IP';

ALTER TABLE "base_job" ADD COLUMN IF NOT EXISTS "current_definition_version_id" integer DEFAULT NULL;
COMMENT ON COLUMN "base_job"."current_definition_version_id" IS '当前流程定义版本ID，普通任务及旧配置可空';
ALTER TABLE "base_job_log" ADD COLUMN IF NOT EXISTS "definition_version_id" integer DEFAULT NULL;
COMMENT ON COLUMN "base_job_log"."definition_version_id" IS '本轮不可变流程定义版本ID，普通任务为空';
CREATE INDEX IF NOT EXISTS "idx_job_current_definition_version" ON "base_job" ("current_definition_version_id");
CREATE INDEX IF NOT EXISTS "idx_job_log_definition_version" ON "base_job_log" ("definition_version_id");

-- 混合新旧流程运行时整笔事务中止，避免不准确的统计。
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM base_job_log old_run JOIN base_job_log new_run ON new_run.job_id = old_run.job_id WHERE old_run.job_type = 1 AND old_run.definition_version_id IS NULL AND new_run.job_type = 1 AND new_run.definition_version_id IS NOT NULL) THEN
        RAISE EXCEPTION '存在同一流程的新旧运行混合记录，请先处理再迁移';
    END IF;
END; $$;

-- 无新版运行的受影响流程配置重置统计；独立普通任务不受影响。
UPDATE base_job SET last_job_log_id = NULL, last_execute_time = NULL, last_end_time = NULL, last_status = NULL, last_duration_ms = NULL, last_dispatch_duration_ms = NULL, last_tracking_version = NULL, execute_count = 0, success_count = 0, fail_count = 0, total_duration_ms = 0, duration_sample_count = 0, stats_since = CURRENT_TIMESTAMP
WHERE job_type = 1
  AND EXISTS (SELECT 1 FROM base_job_log old_run WHERE old_run.job_id = base_job.id AND old_run.job_type = 1 AND old_run.definition_version_id IS NULL)
  AND NOT EXISTS (SELECT 1 FROM base_job_log new_run WHERE new_run.job_id = base_job.id AND new_run.job_type = 1 AND new_run.definition_version_id IS NOT NULL);

-- 仅清理旧流程运行关联的节点业务日志，不按任务类或job_id扩大范围。
DELETE FROM base_job_log child USING base_job_flow_node_run node, base_job_log parent
WHERE node.job_log_id = child.id AND parent.id = node.flow_log_id
  AND parent.job_type = 1 AND parent.definition_version_id IS NULL AND child.trigger_source = 3;
DELETE FROM base_job_flow_node_run node USING base_job_log parent
WHERE parent.id = node.flow_log_id AND parent.job_type = 1 AND parent.definition_version_id IS NULL;
DELETE FROM base_job_log WHERE job_type = 1 AND definition_version_id IS NULL;
ALTER TABLE "base_job_log" DROP COLUMN IF EXISTS "flow_snapshot";

COMMIT;
